    'train.guide.video': 'How to film videos the AI can learn from',
    'train.guide.video.1': 'Keep the whole body in frame, camera still, clean background, good light. Use 60 fps for fast moves.',
    'train.guide.video.2': 'Action recognition: one move per clip, labelled with its name. At least 2 labels; 5–10 clips per label is better.',
    'train.guide.video.3': 'Several people performing the same move (different builds and clothes) keeps the AI from memorising one person.',
    'train.guide.video.4': 'Motion scoring: mark the master\'s videos as "Reference" (more reference performers is better); other videos are scored 0–100.',
    'train.guide.video.5': 'Add diagonal/side angles to reduce errors when limbs are hidden during turns.',
    'train.guide.video.6': 'Only upload videos you have the right to use, with consent from the people in them.',
